def make_palindrome(string: str) -> str:
    """ Find the longest palindrome suffix and construct the shortest palindrome."""
    if not string:
        return string

    # Find the longest palindromic suffix
    for i in range(len(string), 0, -1):
        if string[i:] == string[i:][::-1]:
            # Found the longest palindromic suffix
            return string + string[:len(string) - i][::-1]

    # If no palindromic suffix found (e.g., empty string)
    return string + string[::-1]
